-- Generated by npm run campaign:sql. Apply after 002_secure_campaign.sql.
alter table public.campaign_chapters add column if not exists scenes jsonb not null default '[]'::jsonb;
update public.campaign_chapters set scenes='[{"label":"核对夜间车册","description":"雨水将墨迹晕开，只有第十三栏的纸面仍干燥。","skill":"调查","dc":12,"success":"你们发现这一栏是事后用另一种墨水添上的。","failure":"守卫收走车册，却漏下一张沾灰的副页。","clue":"伪造的放行记录","flag":"register"},{"label":"问守门人最后一件小事","description":"老守门人不敢说马车，却记得马蹄踏过桥石的节奏。","skill":"洞悉","dc":13,"success":"他承认听见过一声不属于马车的钟响。","failure":"他闭口不谈，但你们知道有人在看着他。","clue":"第十三声钟","flag":"bell"}]'::jsonb where id=0;
update public.campaign_chapters set scenes='[{"label":"查看铜匣封蜡","description":"蜡上有三代前的工匠印，新的刀痕却划开了边缘。","skill":"调查","dc":13,"success":"你们找到藏在封口里的第二把钥匙。","failure":"刀痕割断了纸条，地址只剩半截。","clue":"匣中钥匙","flag":"second_key"},{"label":"与寄存铺掌柜对账","description":"账簿里每年都有人替这只匣子续费，署名各不相同。","skill":"说服","dc":14,"success":"掌柜交出最近一次付款的收据。","failure":"掌柜要求你们先证明自己不是来灭口的。","clue":"匿名收据","flag":"receipt"}]'::jsonb where id=1;
update public.campaign_chapters set scenes='[{"label":"记录灯光顺序","description":"两座塔一明一暗，第三座塔总迟一拍。","skill":"奥秘","dc":13,"success":"灯语指向一处明日才会发生的会面。","failure":"你们只能辨认出钟楼与河岸两个词。","clue":"明日会面","flag":"meeting"},{"label":"攀上废塔屋顶","description":"瓦片松动，下面有人刚铺过防雨的绳索。","skill":"运动","dc":14,"success":"你们在塔顶找到一枚新的议会铜扣。","failure":"巡夜人注意到塔顶有动静，搜查加紧。","clue":"议会铜扣","flag":"copper_badge"}]'::jsonb where id=2;
update public.campaign_chapters set scenes='[{"label":"比对宴会座次","description":"每张请柬都有签名，主人那一席的墨水却没有干。","skill":"调查","dc":14,"success":"缺席者在宴会开始后仍有人替他签过名。","failure":"一名宾客拿走了关键的席位卡。","clue":"主人代签","flag":"proxy"},{"label":"和档案员伊莱娅交谈","description":"她将一个空酒杯摆到主人座前，等待你们先说出怀疑。","skill":"洞悉","dc":13,"success":"她说出今晚收到过第二份请柬。","failure":"她只肯留下自己的地址，明日再谈。","clue":"第二份请柬","flag":"second_invite"}]'::jsonb where id=3;
update public.campaign_chapters set scenes='[{"label":"测绘暗室","description":"地砖下的暗槽沿整条街延伸，图纸刻意避开了井。","skill":"调查","dc":14,"success":"你们定位了运输契约的隐蔽通道。","failure":"机械锁响起，来人已知道暗室有人。","clue":"暗槽路线","flag":"route"},{"label":"检查售地地图","description":"地块编号与现有房屋不符，仿佛整条街已经搬走。","skill":"洞悉","dc":15,"success":"你们发现仍有人居住的街区被标作空地。","failure":"地图背面的出资人名字被刮去。","clue":"被抹去的住户","flag":"residents"}]'::jsonb where id=4;
update public.campaign_chapters set scenes='[{"label":"追查账本缺页","description":"修表匠穆雷故意把钟拨慢，给你们留了一刻钟。","skill":"调查","dc":14,"success":"缺页对应一笔付给夜巡队的护送费。","failure":"巡逻队先一步带走账本，你们记下了日期。","clue":"护送费","flag":"escort"},{"label":"安抚搬运工","description":"他们担心说出名字后失去工作。","skill":"说服","dc":13,"success":"一名工人指出马车的秘密卸货处。","failure":"他们拒绝作证，但愿意在暗处放哨。","clue":"灰市卸货点","flag":"loading"}]'::jsonb where id=5;
update public.campaign_chapters set scenes='[{"label":"鉴别白蕨孢子","description":"温室最底层的花盆里留有矿水的苦味。","skill":"求生","dc":13,"success":"孢子证明矿坑废液被运进贵族宅邸。","failure":"你们只带走了破碎的叶片。","clue":"矿水白蕨","flag":"fern"},{"label":"询问园丁","description":"园丁手上的灼伤与花房的浇灌工具一致。","skill":"洞悉","dc":14,"success":"他承认每周有人送来封口的银桶。","failure":"他不肯出卖雇主，但指给你们桶上的印记。","clue":"银桶印记","flag":"silver_barrel"}]'::jsonb where id=6;
update public.campaign_chapters set scenes='[{"label":"比对三封遗言","description":"同一个词在三封信里拼写各异。","skill":"调查","dc":14,"success":"报社那封信的最后一句是伪造的。","failure":"纸被雨打湿，你们仍记住了共同的落款。","clue":"伪造的尾句","flag":"forged_line"},{"label":"寻找送信人","description":"年轻信使从来没见过收信的议员。","skill":"说服","dc":15,"success":"信使愿意带你们去真正的交接地点。","failure":"他逃进人群，掉下一枚旧城区车票。","clue":"交接地点","flag":"handoff"}]'::jsonb where id=7;
update public.campaign_chapters set scenes='[{"label":"重走夜巡路线","description":"地图上的巡逻点间隔不合理，恰好绕开一条小巷。","skill":"调查","dc":14,"success":"失踪的巡逻记录指向运货的夜晚。","failure":"队长警惕你们，但放行了对小巷的调查。","clue":"缺失巡逻段","flag":"patrol_gap"},{"label":"为被诬陷者找证人","description":"卖茶人看到了两套制服在换班后相互交换。","skill":"说服","dc":14,"success":"证人愿意在安全地点出面。","failure":"证人只肯匿名写下所见。","clue":"换班证词","flag":"shift_witness"}]'::jsonb where id=8;
update public.campaign_chapters set scenes='[{"label":"拓下地契印记","description":"印章的缺口与旧议会纪念碑上的缺口完全吻合。","skill":"调查","dc":15,"success":"地契沿用的确是真正的旧章。","failure":"拓印不完整，但年代没有错。","clue":"旧议会真章","flag":"real_seal"},{"label":"在街坊会议发言","description":"人们关心的不是文书，而是明早会不会被赶走。","skill":"说服","dc":14,"success":"街坊选出三名代表与你们同行。","failure":"众人保持观望，仍借给你们一间议事屋。","clue":"街坊代表","flag":"delegates"}]'::jsonb where id=9;
update public.campaign_chapters set scenes='[{"label":"潜入拍卖后台","description":"买家名单有一栏以你们的队名登记。","skill":"潜行","dc":15,"success":"你们抄到了幕后担保人的名字。","failure":"保安发现脚印，你们只能记下拍卖地点。","clue":"幕后担保人","flag":"guarantor"},{"label":"试探戴面具的买家","description":"买家愿意谈价，却先问你们有没有原始契约。","skill":"洞悉","dc":14,"success":"她是受命试探所有寻找档案的人。","failure":"她留下半张写着会面时间的卡片。","clue":"试探者","flag":"masked_buyer"}]'::jsonb where id=10;
update public.campaign_chapters set scenes='[{"label":"拆开钟楼传动轴","description":"齿轮每十三次转动会露出一条刻字。","skill":"奥秘","dc":15,"success":"刻字告诉你们暗格不在钟里，而在钟声投影处。","failure":"齿轮卡住，惊醒了守塔机械。","clue":"投影暗格","flag":"shadow_box"},{"label":"与守塔人交换故事","description":"守塔人反复询问谁有资格为城市敲钟。","skill":"说服","dc":14,"success":"他交给你们一枚旧议会通行牌。","failure":"他仍让你们在塔内过夜以躲开搜捕。","clue":"通行牌","flag":"tower_pass"}]'::jsonb where id=11;
update public.campaign_chapters set scenes='[{"label":"修补浸水目录","description":"字迹在灯火下显出被刮去的街道名称。","skill":"调查","dc":14,"success":"你们找到了被删除的选区名单。","failure":"墨水再次晕开，但馆长记得页码。","clue":"旧选区名单","flag":"wards"},{"label":"说服馆长开放密柜","description":"赛洛要你们承诺让档案对所有居民开放。","skill":"说服","dc":15,"success":"密柜里保存了原始投票记录。","failure":"她只交给你们一份可公开的抄本。","clue":"投票原件","flag":"vote_original"}]'::jsonb where id=12;
update public.campaign_chapters set scenes='[{"label":"跟随白鸦","description":"白鸦在三处窗台停留，却从不靠近最亮的灯。","skill":"求生","dc":14,"success":"你们找到它与失踪议员往来的暗窗。","failure":"它飞走前落下一根沾着印泥的羽毛。","clue":"暗窗","flag":"raven_window"},{"label":"营救驯养人","description":"驯养人被关在没有锁的房间，门外却有人看守。","skill":"潜行","dc":15,"success":"你们带出他和一枚刻有收件地址的脚环。","failure":"他趁守卫换班自行逃出，约你们河边见。","clue":"收件脚环","flag":"raven_ring"}]'::jsonb where id=13;
update public.campaign_chapters set scenes='[{"label":"校验两份文书年代","description":"纸张同样古老，签名的职务却隔了三十年。","skill":"调查","dc":15,"success":"你们证明后来者借用死者的印章。","failure":"日期问题仍无法解释，你们标出需要追问的人。","clue":"借章者","flag":"borrowed_seal"},{"label":"质问登记官","description":"登记官只愿公开一份不完整的收件簿。","skill":"洞悉","dc":16,"success":"他在被问及缺页时看向了执政官的办公室。","failure":"他销毁了自己的便条，但你们记住他的迟疑。","clue":"执政官线索","flag":"chancellor"}]'::jsonb where id=14;
update public.campaign_chapters set scenes='[{"label":"用故事换过桥权","description":"水道居民不问出身，只问你们失去过什么。","skill":"说服","dc":14,"success":"他们为你们指认能避开巡逻的地下路。","failure":"他们收下故事，仍要求你们走公开的渡口。","clue":"地下渡口","flag":"underpass"},{"label":"辨认面具图案","description":"每张面具的空白处藏着一笔家族旧名。","skill":"调查","dc":15,"success":"你们发现至少三个被驱逐家族仍在这里。","failure":"面具的主人不愿暴露姓名，但留下家徽。","clue":"旧家徽","flag":"old_families"}]'::jsonb where id=15;
update public.campaign_chapters set scenes='[{"label":"检查盐井护甲","description":"守卫铠甲内侧有相同的炼金工坊编号。","skill":"调查","dc":14,"success":"编号将废液与上城区的工坊联系起来。","failure":"锈迹遮住了编号，只剩半枚工坊徽章。","clue":"工坊编号","flag":"workshop"},{"label":"救助受伤守卫","description":"他在清醒时只记得有人命令把井水倒进下水道。","skill":"洞悉","dc":15,"success":"他愿意说出命令者的声音和口音。","failure":"他无法记起名字，但指向废井的北侧。","clue":"命令者口音","flag":"accent"}]'::jsonb where id=16;
update public.campaign_chapters set scenes='[{"label":"寻找甲壳兽弱点","description":"巨兽的左侧甲壳会在钟响时张开。","skill":"求生","dc":15,"success":"你们把弱点标记在战斗记录里。","failure":"灰尘遮蔽视线，但它惧怕明亮的灯。","clue":"甲壳缝隙","flag":"weak_spot"},{"label":"避开腐蚀的水面","description":"井边残留着足以灼伤皮肤的绿色液体。","skill":"运动","dc":14,"success":"你们找到一处高台，准备从那里迎敌。","failure":"靴底被腐蚀，下一段路要放慢脚步。","clue":"井边高台","flag":"high_ground"}]'::jsonb where id=17;
update public.campaign_chapters set scenes='[{"label":"核对驱逐案卷","description":"卷宗里有同一个人的两份互相冲突的证词。","skill":"调查","dc":16,"success":"你们找出证人曾被迫改变口供的日期。","failure":"法官允许你们带走副本，但保留原卷。","clue":"被迫改口日期","flag":"recanted"},{"label":"保证证人安全","description":"无名法官把证人的名字写在纸上，等你们提出保护办法。","skill":"说服","dc":15,"success":"他答应在听证会上亲自作证。","failure":"他只派一名信使与你们同行。","clue":"法官承诺","flag":"judge_ally"}]'::jsonb where id=18;
update public.campaign_chapters set scenes='[{"label":"询问归来的议员","description":"议员承认销毁过证词，却说那是为了保护活着的人。","skill":"洞悉","dc":16,"success":"他隐瞒了谁下令，但没有隐瞒动机。","failure":"他避开了你们的问题，留下旧会议时间。","clue":"隐瞒的命令","flag":"hidden_order"},{"label":"找回议员藏信","description":"他把真正的信放在昔日演讲台的底座里。","skill":"调查","dc":15,"success":"信中有一份尚未公开的证人名单。","failure":"你们找到信封，内文已被人拿走。","clue":"证人名单","flag":"witness_list"}]'::jsonb where id=19;
update public.campaign_chapters set scenes='[{"label":"复原镜厅脚印","description":"几十道影子中只有一双鞋在熄灯时逆着人群走。","skill":"调查","dc":16,"success":"你们确定刺客并非证人的随行者。","failure":"脚印被踩乱，但鞋跟上留有军械库的泥。","clue":"逆行脚印","flag":"reverse_steps"},{"label":"保护证人离场","description":"一面镜子后的暗门正通向楼梯。","skill":"潜行","dc":15,"success":"你们带证人避开了追击。","failure":"证人安全离场，但刺客看清了你们的脸。","clue":"镜后暗门","flag":"mirror_exit"}]'::jsonb where id=20;
update public.campaign_chapters set scenes='[{"label":"找出停钟机关","description":"钟楼的总控线来自执政官办公室，而非工匠行会。","skill":"奥秘","dc":16,"success":"你们恢复了一座钟，留下机关上的指纹。","failure":"机关被锁死，你们记录了控制方向。","clue":"停钟机关","flag":"clock_switch"},{"label":"与改革派谈条件","description":"改革派承诺公开证据，却要求你们先放弃地下居民的席位。","skill":"洞悉","dc":15,"success":"你们发现他们内部也有人反对这个条件。","failure":"他们暂不让步，但愿意参加下一场公开会议。","clue":"改革派分歧","flag":"reform_split"}]'::jsonb where id=21;
update public.campaign_chapters set scenes='[{"label":"寻找断桥的替代路","description":"桥下的旧检修道曾由灰市工人维护。","skill":"求生","dc":15,"success":"曾受帮助的工人替你们开了检修门。","failure":"检修门锈死，你们只能从桥墩攀过去。","clue":"桥下检修道","flag":"bridge_tunnel"},{"label":"向卫队出示证据","description":"他们的命令没有签署人，只有一枚熟悉的假印。","skill":"说服","dc":17,"success":"一名守卫放你们通过，并记下文书上的矛盾。","failure":"卫队不放行，却给你们一刻钟后撤。","clue":"无签署封桥令","flag":"unsigned_order"}]'::jsonb where id=22;
update public.campaign_chapters set scenes='[{"label":"组织救火队","description":"档案室和馆员宿舍只能先救一处。","skill":"说服","dc":15,"success":"馆员同意先疏散，再合力保存原件。","failure":"火势迫使你们带走部分抄本。","clue":"救出的原件","flag":"saved_records"},{"label":"追踪纵火者","description":"煤灰落在同一种皮靴的鞋纹里。","skill":"调查","dc":16,"success":"鞋纹通向雇佣兵临时驻地。","failure":"你们在火场外发现未点燃的油瓶。","clue":"雇佣兵鞋纹","flag":"arson_boot"}]'::jsonb where id=23;
update public.campaign_chapters set scenes='[{"label":"主持街区议事","description":"四个派系各派代表，所有人都要求先保证安全。","skill":"说服","dc":16,"success":"居民愿意共同监督下一场表决。","failure":"争论没有结束，但没人离席。","clue":"居民监督","flag":"citizen_watch"},{"label":"统计各派诉求","description":"相似的要求被不同人用不同措辞提出。","skill":"调查","dc":15,"success":"你们提炼出三条所有派系都可接受的底线。","failure":"议事记录仍有分歧，你们留下原稿。","clue":"共同底线","flag":"common_ground"}]'::jsonb where id=24;
update public.campaign_chapters set scenes='[{"label":"鉴定契约原件","description":"契约上有四种不同墨水，最旧的一种在纸张背面。","skill":"调查","dc":17,"success":"你们证明公民议会条款并非后人添加。","failure":"你们只证明了纸张年代，仍需更多证人。","clue":"契约原始条款","flag":"charter"},{"label":"邀请地下代表","description":"代表要求城市里每个无名者都能保有投票权。","skill":"说服","dc":16,"success":"他们同意带来历史见证人。","failure":"他们先派观察者，等待你们公开承诺。","clue":"地下代表","flag":"under_delegate"}]'::jsonb where id=25;
update public.campaign_chapters set scenes='[{"label":"核对护卫命令","description":"最后的守门人凯尔拿到的命令有两处日期相互矛盾。","skill":"调查","dc":16,"success":"他看出伪造之处，命部下收起武器。","failure":"他仍拦住道路，但愿意听取证词。","clue":"伪造护卫令","flag":"guard_order"},{"label":"争取凯尔的信任","description":"他曾发誓保护城市，而不是一个办公室。","skill":"说服","dc":17,"success":"凯尔允许一名证人通过。","failure":"他要求你们先把证据交给公证人。","clue":"凯尔的条件","flag":"kael_terms"}]'::jsonb where id=26;
update public.campaign_chapters set scenes='[{"label":"测量大厅掩体","description":"雇佣兵从两侧门进入，平民仍在长桌旁。","skill":"调查","dc":16,"success":"你们找到可保护档案的石柱。","failure":"桌子挡住了视线，你们先安排疏散。","clue":"大厅石柱","flag":"pillar"},{"label":"劝平民撤离","description":"他们担心离开后证据会被销毁。","skill":"说服","dc":16,"success":"平民留下见证人，其他人撤到安全处。","failure":"人群缓慢退开，留给你们的时间缩短。","clue":"撤离见证人","flag":"evacuation"}]'::jsonb where id=27;
update public.campaign_chapters set scenes='[{"label":"公开所有证据","description":"旧贵族、改革派与地下居民都在等待你们先开口。","skill":"说服","dc":17,"success":"各派同意让普通居民发言。","failure":"会场出现质疑，你们仍有原件可供查验。","clue":"公开证据","flag":"public_record"},{"label":"准备最终表决","description":"投票册上还有被驱逐者的空白栏。","skill":"调查","dc":16,"success":"你们补回遗漏选区的名单。","failure":"时间不足，你们把名单留给下一届议会。","clue":"补回的选区","flag":"restored_wards"}]'::jsonb where id=28;
update public.campaign_chapters set scenes='[{"label":"回访旧盟友","description":"你们沿着一路走过的街道，听见不同人讲述同一夜。","skill":"洞悉","dc":14,"success":"旧盟友愿意为你们的选择留下证言。","failure":"有人仍不赞成结果，却愿意继续对话。","clue":"盟友后日谈","flag":"allies_epilogue"},{"label":"整理队伍编年史","description":"每个人在第一页写下最初来到城门的理由。","skill":"调查","dc":13,"success":"你们保存了所有人的名字与选择。","failure":"几页笔记遗失，但队伍记录仍在。","clue":"队伍编年史","flag":"chronicle"}]'::jsonb where id=29;
